CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role='admin'));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.has_chat_admin_role() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.has_chat_admin_role() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_chat_admin_role() TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_chat_ids(_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid,username text,display_name text,code text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_chat_admin_role() THEN RAISE EXCEPTION 'هذه القائمة للمديرة فقط'; END IF; RETURN QUERY SELECT p.id,p.username,p.display_name,c.code FROM public.profiles p JOIN public.chat_ids c ON c.user_id=p.id ORDER BY p.id LIMIT 50 OFFSET greatest(0,_offset); END $$;
REVOKE ALL ON FUNCTION public.admin_chat_ids(integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_chat_ids(integer) TO authenticated;
CREATE TABLE public.chat_preferences (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, hide_presence boolean NOT NULL DEFAULT false, sound_enabled boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE ON public.chat_preferences TO authenticated; GRANT ALL ON public.chat_preferences TO service_role;
ALTER TABLE public.chat_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_chat_preferences ON public.chat_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.chat_history_clears (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, friendship_id uuid NOT NULL REFERENCES public.chat_friendships(id) ON DELETE CASCADE, cleared_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,friendship_id));
GRANT SELECT ON public.chat_history_clears TO authenticated; GRANT ALL ON public.chat_history_clears TO service_role;
ALTER TABLE public.chat_history_clears ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_chat_clears ON public.chat_history_clears FOR SELECT TO authenticated USING(user_id=auth.uid());
DROP POLICY chat_message_participant ON public.chat_messages;
CREATE POLICY chat_message_participant ON public.chat_messages FOR SELECT TO authenticated USING(created_at>now()-interval '3 days' AND EXISTS(SELECT 1 FROM public.chat_friendships f WHERE f.id=friendship_id AND auth.uid() IN(f.requester_id,f.recipient_id)) AND NOT EXISTS(SELECT 1 FROM public.chat_history_clears c WHERE c.user_id=auth.uid() AND c.friendship_id=chat_messages.friendship_id AND chat_messages.created_at<=c.cleared_at));
CREATE OR REPLACE FUNCTION public.clear_chat_history(_friendship uuid,_both boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); f public.chat_friendships; BEGIN SELECT * INTO f FROM public.chat_friendships WHERE id=_friendship AND u IN(requester_id,recipient_id) FOR UPDATE; IF u IS NULL OR f.id IS NULL THEN RAISE EXCEPTION 'المحادثة غير متاحة'; END IF; INSERT INTO public.chat_history_clears(user_id,friendship_id,cleared_at) VALUES(u,f.id,now()) ON CONFLICT(user_id,friendship_id) DO UPDATE SET cleared_at=excluded.cleared_at; IF _both THEN INSERT INTO public.chat_history_clears(user_id,friendship_id,cleared_at) VALUES(CASE WHEN f.requester_id=u THEN f.recipient_id ELSE f.requester_id END,f.id,now()) ON CONFLICT(user_id,friendship_id) DO UPDATE SET cleared_at=excluded.cleared_at; UPDATE public.chat_messages SET body=NULL,deleted_at=now() WHERE friendship_id=f.id; DELETE FROM public.notifications WHERE chat_id=f.id AND type='chat_message'; END IF; END $$;
REVOKE ALL ON FUNCTION public.clear_chat_history(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.clear_chat_history(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.chat_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); BEGIN IF u IS NULL THEN RAISE EXCEPTION 'يجب تسجيل الدخول'; END IF; RETURN jsonb_build_object('friendships',coalesce((SELECT jsonb_agg(x ORDER BY x.updated_at DESC) FROM (SELECT f.*,p.username,p.display_name,p.avatar_url,p.id AS peer_id,CASE WHEN coalesce(s.hide_presence,false) THEN NULL ELSE p.last_seen_at END AS last_seen_at,CASE WHEN coalesce(s.hide_presence,false) THEN false ELSE p.is_online AND p.last_seen_at>now()-interval '30 seconds' END AS is_online,coalesce(s.hide_presence,false) AS presence_hidden,EXISTS(SELECT 1 FROM public.chat_blocks b WHERE b.blocker_id=u AND b.blocked_id=p.id) AS blocked_by_me,EXISTS(SELECT 1 FROM public.chat_blocks b WHERE b.blocker_id=p.id AND b.blocked_id=u) AS blocked_by_peer,(SELECT body FROM public.chat_messages m WHERE m.friendship_id=f.id AND m.created_at>now()-interval '3 days' AND m.created_at>coalesce(c.cleared_at,'-infinity') ORDER BY created_at DESC LIMIT 1) AS last_body,(SELECT max(created_at) FROM public.chat_messages m WHERE m.friendship_id=f.id AND m.created_at>now()-interval '3 days' AND m.created_at>coalesce(c.cleared_at,'-infinity')) AS last_message_at,(SELECT count(*) FROM public.chat_messages m WHERE m.friendship_id=f.id AND m.created_at>now()-interval '3 days' AND m.created_at>coalesce(c.cleared_at,'-infinity') AND m.sender_id<>u AND m.read_at IS NULL AND m.deleted_at IS NULL) AS unread FROM public.chat_friendships f JOIN public.profiles p ON p.id=CASE WHEN f.requester_id=u THEN f.recipient_id ELSE f.requester_id END LEFT JOIN public.chat_preferences s ON s.user_id=p.id LEFT JOIN public.chat_history_clears c ON c.user_id=u AND c.friendship_id=f.id WHERE u IN(f.requester_id,f.recipient_id) AND (c.cleared_at IS NULL OR f.updated_at>c.cleared_at)) x),'[]'::jsonb)); END $$;
CREATE OR REPLACE FUNCTION public.purge_expired_chat() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.chat_messages WHERE created_at<=now()-interval '3 days'; DELETE FROM public.notifications WHERE type='chat_message' AND created_at<=now()-interval '3 days'; DELETE FROM public.push_deliveries WHERE event_id IN(SELECT id FROM public.push_events WHERE kind='chat_message' AND created_at<=now()-interval '3 days'); DELETE FROM public.push_events WHERE kind='chat_message' AND created_at<=now()-interval '3 days'; END $$;
REVOKE ALL ON FUNCTION public.purge_expired_chat() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.purge_expired_chat() TO service_role;
CREATE INDEX chat_messages_expiry ON public.chat_messages(created_at);
CREATE EXTENSION IF NOT EXISTS pg_cron;
ALTER PUBLICATION supabase_realtime ADD TABLE public.chat_history_clears;
COMMENT ON TABLE public.chat_messages IS 'Text-only transient delivery store: reads expire at 72 hours; hourly purge physically removes expired rows. Managed snapshots may retain previous data.';